/**
 * Placeholder for routes whose module has not landed yet. Replace the route element
 * with the real page in the owning module's PR; do not edit this file for that.
 */
import { useLocation } from "react-router";
import { Construction } from "lucide-react";
import { PORTAL_NAV, STAFF_NAV } from "@/app/navigation";
import { Card, EmptyState, Page, PageHeader } from "@/components/ui";

export function ModulePlaceholder() {
  const { pathname } = useLocation();
  const item = [...STAFF_NAV, ...PORTAL_NAV]
    .flatMap((g) => g.items)
    .filter((i) => pathname === i.to || pathname.startsWith(`${i.to}/`))
    .sort((a, b) => b.to.length - a.to.length)[0];

  return (
    <Page>
      <PageHeader title={item?.label ?? "Coming soon"} eyebrow={item?.owner} />
      <Card>
        <EmptyState
          icon={<Construction />}
          title="This module is being built"
          description={
            item
              ? `Owned by ${item.owner}. The route, navigation and permissions are wired; the page lands with the module PR.`
              : "This page lands with its module PR."
          }
        />
      </Card>
    </Page>
  );
}
